/// <summary>
/// Data contract for Standard vendor claim journal process
/// </summary>
[DataContract]
internal final class METVendClaimJournalContract
{
    NoYesId   postClaim;
    str       packedQuery;

}

Method.Source:
/// <summary>
/// Indicates whether to post the claim journals after creation
/// </summary>
/// <param name = "_postClaim">Post claims</param>
/// <returns>Post claims</returns>
[DataMemberAttribute, SysOperationLabelAttribute("@SYS86511")]
public NoYesId parmPostClaim(NoYesId _postClaim = postClaim)
{
    postClaim = _postClaim;
    return postClaim;
}

/// <summary>
/// initialise and return query
/// </summary>
/// <param name = "_packedQuery">Site query</param>
/// <returns>Site query</returns>
[DataMemberAttribute, AifQueryTypeAttribute(identifierStr(_packedQuery), queryStr(InventSitesSRS))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Gets the query from packed query
/// </summary>
/// <returns>Query instance</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Sets the packed query from Query instance
/// </summary>
/// <param name = "_query">Query instance</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}
